#!/usr/bin/env node
/**
 * Checks the implemented API against the designed API.
 *
 *   docs/api/openapi.yaml   the design authority, hand-written, reviewed first
 *   docs/api/openapi.json   what the code actually exposes, generated by Scramble
 *
 * Run it with:
 *
 *   pnpm openapi:conformance
 *
 * ## Why this is conformance and not equality
 *
 * The design is written ahead of the code, so for most of the project's life the
 * designed document is larger than the generated one. Demanding equality would
 * make a design-first document impossible to write: the first commit of a new
 * endpoint's contract would fail CI. So the rule is one-directional.
 *
 *   FAILS  an operation exists in the code but not in the design
 *          -> something was built that nobody designed
 *   FAILS  an implemented operation answers with a status the design omits
 *          -> the code promises something the contract does not
 *   FAILS  the two documents disagree about info.version
 *   PASSES an operation exists in the design but not yet in the code
 *          -> that is the remaining backlog, and it is reported as progress
 *
 * It needs neither the database nor a running stack: both inputs are committed
 * files. The companion guarantee - that openapi.json really does match the code
 * - is the "OpenAPI document is current" step in the php-tests CI job.
 */
import { readFileSync } from 'node:fs';
import { parse } from 'yaml';

// Overridable so the checker itself can be exercised against fixtures. CI and
// the pnpm script pass nothing and get the committed documents.
const argumentValue = (flag, fallback) => {
  const index = process.argv.indexOf(flag);
  return index !== -1 && process.argv[index + 1] ? process.argv[index + 1] : fallback;
};

const DESIGN_PATH = argumentValue('--design', 'docs/api/openapi.yaml');
const GENERATED_PATH = argumentValue('--generated', 'docs/api/openapi.json');
const HTTP_METHODS = ['get', 'put', 'post', 'delete', 'patch', 'options', 'head', 'trace'];

const failures = [];
const warnings = [];

const read = (path) => {
  try {
    return readFileSync(path, 'utf8');
  } catch (error) {
    console.error(`Cannot read ${path}: ${error.message}`);
    process.exit(2);
  }
};

const parseDocument = (path, text) => {
  try {
    return path.endsWith('.json') ? JSON.parse(text) : parse(text);
  } catch (error) {
    console.error(`${path} is not valid: ${error.message}`);
    process.exit(2);
  }
};

const designText = read(DESIGN_PATH);
const design = parseDocument(DESIGN_PATH, designText);
const generated = parseDocument(GENERATED_PATH, read(GENERATED_PATH));

/** Collect every $ref in a document, with the location that holds it. */
const collectRefs = (root) => {
  const found = [];
  const walk = (node, path) => {
    if (Array.isArray(node)) {
      node.forEach((value, index) => walk(value, `${path}/${index}`));
      return;
    }
    if (node === null || typeof node !== 'object') return;
    for (const [key, value] of Object.entries(node)) {
      if (key === '$ref' && typeof value === 'string') found.push({ ref: value, at: path });
      else walk(value, `${path}/${key}`);
    }
  };
  walk(root, '#');
  return found;
};

const resolveRef = (root, ref) => {
  if (!ref.startsWith('#/')) return undefined;
  let current = root;
  for (const segment of ref.slice(2).split('/')) {
    const key = segment.replace(/~1/g, '/').replace(/~0/g, '~');
    if (current === null || typeof current !== 'object' || !(key in current)) return undefined;
    current = current[key];
  }
  return current;
};

/**
 * Path keys are compared with their parameter NAMES removed: the design calls it
 * `/orders/{order}` and a generated document may call it `/orders/{id}`, which is
 * the same endpoint. Structure is the contract; the placeholder's spelling is
 * not, so a difference there is a warning rather than a failure.
 */
const normalisePath = (path) => path.replace(/\{[^}]*\}/g, '{}');

const indexOperations = (document) => {
  const index = new Map();
  for (const [path, pathItem] of Object.entries(document.paths ?? {})) {
    if (pathItem === null || typeof pathItem !== 'object') continue;
    for (const method of HTTP_METHODS) {
      const operation = pathItem[method];
      if (!operation) continue;
      index.set(`${method.toUpperCase()} ${normalisePath(path)}`, { path, method, operation });
    }
  }
  return index;
};

// ---------------------------------------------------------------------------
// 1. The design document has to be sound on its own terms.
// ---------------------------------------------------------------------------
const designRefs = collectRefs(design);
for (const { ref, at } of designRefs) {
  if (resolveRef(design, ref) === undefined) {
    failures.push(`${DESIGN_PATH}: $ref does not resolve: ${ref} (at ${at})`);
  }
}

const designOperations = indexOperations(design);
const operationIds = new Map();
for (const [key, { operation }] of designOperations) {
  const id = operation.operationId;
  if (!id) {
    warnings.push(`${DESIGN_PATH}: ${key} has no operationId`);
    continue;
  }
  operationIds.set(id, [...(operationIds.get(id) ?? []), key]);
}
for (const [id, keys] of operationIds) {
  if (keys.length > 1) {
    failures.push(`${DESIGN_PATH}: operationId "${id}" is used by ${keys.join(' and ')}`);
  }
}

const declaredTags = new Set((design.tags ?? []).map((tag) => tag.name));
for (const [key, { operation }] of designOperations) {
  for (const tag of operation.tags ?? []) {
    if (!declaredTags.has(tag)) {
      failures.push(`${DESIGN_PATH}: ${key} uses tag "${tag}", which is not declared in tags:`);
    }
  }
}

// ---------------------------------------------------------------------------
// 2. The implemented document must conform to it.
// ---------------------------------------------------------------------------
if (design.info?.version !== generated.info?.version) {
  failures.push(
    `info.version differs: design ${design.info?.version} vs generated ${generated.info?.version}. ` +
      'The two documents describe one API at one version; OPENAPI_VERSION sets the generated one.',
  );
}

const generatedOperations = indexOperations(generated);
const statusCodes = (operation) =>
  Object.keys(operation.responses ?? {}).filter((code) => /^[1-5][0-9][0-9]$/.test(code));

for (const [key, built] of generatedOperations) {
  const designed = designOperations.get(key);

  if (!designed) {
    failures.push(
      `undesigned operation: ${built.method.toUpperCase()} ${built.path} is implemented but absent ` +
        `from ${DESIGN_PATH}. Design it first, then implement it.`,
    );
    continue;
  }

  if (designed.path !== built.path) {
    warnings.push(
      `path parameter named differently: design "${designed.path}" vs code "${built.path}"`,
    );
  }

  const designedCodes = new Set(statusCodes(designed.operation));
  for (const code of statusCodes(built.operation)) {
    if (!designedCodes.has(code)) {
      failures.push(
        `undesigned response: ${built.method.toUpperCase()} ${built.path} answers ${code}, which ` +
          `${DESIGN_PATH} does not promise. Either document it or stop returning it.`,
      );
    }
  }
}

// ---------------------------------------------------------------------------
// 3. Report.
// ---------------------------------------------------------------------------
const implemented = [...generatedOperations.keys()].filter((key) => designOperations.has(key));
const pending = [...designOperations.keys()].filter((key) => !generatedOperations.has(key));
const provisional = designText
  .split('\n')
  .filter((line) => line.includes('x-provisional: true')).length;

console.log('OpenAPI design conformance');
console.log(
  `  design     ${DESIGN_PATH}  ${designOperations.size} operations, ${provisional} provisional`,
);
console.log(`  generated  ${GENERATED_PATH}  ${generatedOperations.size} operations`);
console.log(`  conforming ${implemented.length} of ${generatedOperations.size} implemented`);
console.log(`  designed, not yet built: ${pending.length}`);

if (process.env.OPENAPI_CONFORMANCE_VERBOSE === '1' && pending.length) {
  console.log('\nRemaining backlog:');
  for (const key of pending.sort()) console.log(`  ${key}`);
}

if (warnings.length) {
  console.log(`\nWarnings (${warnings.length}):`);
  for (const warning of warnings) console.log(`  ${warning}`);
}

if (failures.length) {
  console.error(`\nFailures (${failures.length}):`);
  for (const failure of failures) console.error(`  ${failure}`);
  console.error('\nThe code and the designed contract disagree. The design is the authority.');
  process.exit(1);
}

console.log('\nThe implemented API conforms to the designed contract.');
